  const tiers = [];
  for (let k = 0; k < bo.length; k++) {
    if (['Basic Economy', 'Main Cabin', 'Main Plus', 'Main Select', 'First'].includes(bo[k])) {
      const tierName = bo[k];
      const tierPrice = bo[k+1];
      const tierDetails = [];
      for (let m = k + 2; m < bo.length && m < k + 14; m++) {
        if (['Basic Economy', 'Main Cabin', 'Main Plus', 'Main Select', 'First', 'Fare and baggage', 'Prices include'].some(x => bo[m].startsWith(x))) {
          break;
        }
        if (bo[m] !== 'Continue') tierDetails.push(bo[m]);
      }
      tiers.push({ name: tierName, price: tierPrice, details: tierDetails });
    }
  }

  return {
    combo: i + 1,
    outDate: c.outDate,
    retDate: c.retDate,
    nights: c.nights,
    airline: outAirline,
    outbound: {
      date: outDateStr,
      departure: outDepTime,
      arrival: outArrTime,
      duration: outDuration,
      stops: outStops
    },
    returnFlight: {
      date: retDateStr,
      departure: retDepTime,
      arrival: retArrTime,
      duration: retDuration,
      stops: retStops
    },
    lowestPrice: tiers[0]?.price || "Unknown",
    lowestTier: tiers[0]?.name || "Unknown",
    tiers,
    cheapest1StopFallback: c.cheapestDepOverall?.isNonstop ? "None needed (cheapest is already nonstop)" : `${c.cheapestDepOverall?.airline} ($${c.cheapestDepOverall?.price})`
  };
