      }
      p = p.parentElement;
    }
    return {
      price: el.textContent.trim(),
      cardTag: card?.tagName,
      cardClass: card?.className,
      cardText: (card || el.parentElement?.parentElement)?.innerText?.replace(/\n+/g, ' | ')
    };
  });
});

