async function checkFlight(outDate, retDate) {
  const url = `https://www.google.com/travel/flights?q=Flights%20from%20JAX%20to%20PHX%20on%20${outDate}%20through%20${retDate}`;
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "domcontentloaded", timeout_ms: 10000 });
  await new Promise(r => setTimeout(r, 2500));

  // Extract departing options
  const departing = await browserjs(tabId, () => {
    const cards = Array.from(document.querySelectorAll('div.JMc5Xc'));
    return cards.map(c => ({
      ariaLabel: c.getAttribute('aria-label') || '',
      text: c.innerText.replace(/\n+/g, ' | ')
    }));
  });

  return { outDate, retDate, departingCount: departing.length, departing: departing.slice(0, 5) };
}

