const tabId = 725789989;

async function getFlightDetails(outDate, retDate) {
  const searchUrl = `https://www.google.com/travel/flights?q=Flights%20from%20JAX%20to%20PHX%20on%20${outDate}%20through%20${retDate}`;
  await tool.navigate({ tabId, url: searchUrl });
  await tool.wait_for({ tabId, condition: "load_state", value: "domcontentloaded", timeout_ms: 10000 });
  await new Promise(r => setTimeout(r, 3000));

  // 1. Get departing flights
  const depCards = await browserjs(tabId, () => {
    const cards = Array.from(document.querySelectorAll('div.JMc5Xc'));
    return cards.map((c, idx) => ({
      idx,
      label: c.getAttribute('aria-label') || ''
    }));
  });

  if (!depCards || depCards.length === 0) {
    return { outDate, retDate, error: "No departing flights found" };
  }

  // Find nonstop or cheapest
  const nonstopDep = depCards.find(c => c.label.includes('Nonstop'));
  const cheapestDep = depCards[0];
  const chosenDep = nonstopDep || cheapestDep;

  // Click the chosen departing flight
  await browserjs(tabId, (idx) => {
    const cards = Array.from(document.querySelectorAll('div.JMc5Xc'));
    if (cards[idx]) cards[idx].click();
  }, chosenDep.idx);

  await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 4000 });
  await new Promise(r => setTimeout(r, 2000));

  // 2. Get returning flights
  const retCards = await browserjs(tabId, () => {
    const cards = Array.from(document.querySelectorAll('div.JMc5Xc'));
    return cards.map((c, idx) => ({
      idx,
      label: c.getAttribute('aria-label') || ''
    }));
  });

  let chosenRet = null;
  if (retCards && retCards.length > 0) {
    const nonstopRet = retCards.find(c => c.label.includes('Nonstop'));
    chosenRet = nonstopRet || retCards[0];

    // Click the chosen returning flight
    await browserjs(tabId, (idx) => {
      const cards = Array.from(document.querySelectorAll('div.JMc5Xc'));
      if (cards[idx]) cards[idx].click();
    }, chosenRet.idx);

    await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 4000 });
    await new Promise(r => setTimeout(r, 2500));
  }

  // 3. Extract summary and booking options
  const details = await browserjs(tabId, () => {
    const bodyText = document.body.innerText;
    // Extract booking options container if present
    const options = [];
    const bookingHeaders = Array.from(document.querySelectorAll('h3, div')).filter(d => 
      ['Basic Economy', 'Main Cabin', 'Economy', 'Wanna Get Away', 'Main Plus', 'Main Select', 'First'].some(tier => d.textContent.trim() === tier)
    );

    return {
      url: window.location.href,
      fullTextSnippet: bodyText.slice(0, 3000)
    };
  });

  return {
    outDate,
    retDate,
    chosenDepLabel: chosenDep.label,
    chosenRetLabel: chosenRet ? chosenRet.label : null,
    hasNonstopOut: !!nonstopDep,
    hasNonstopRet: chosenRet ? chosenRet.label.includes('Nonstop') : false,
    detailsSnippet: details.fullTextSnippet
  };
}

