    await new Promise(r => setTimeout(r, 2500));
  }

  // 3. Extract final summary & booking tiers
  const finalSummary = await browserjs(tabId, () => {
    const text = document.body.innerText;
    const lines = text.split('\n').map(l => l.trim()).filter(Boolean);
    const selIdx = lines.indexOf("Selected flights");
    const bookIdx = lines.findIndex(l => l.startsWith("Booking options"));
    const priceIdx = lines.findIndex(l => l.startsWith("Price insights"));

    return {
      url: window.location.href,
      selectedFlights: selIdx !== -1 && bookIdx !== -1 ? lines.slice(selIdx, bookIdx) : [],
      bookingOptions: bookIdx !== -1 ? lines.slice(bookIdx, priceIdx !== -1 ? priceIdx : bookIdx + 60) : []
    };
  });

  return {
    outDate,
    retDate,
    nights,
    depLabel: chosenDep.label,
    retLabel: chosenRet ? chosenRet.label : null,
    hasNonstopOut: !!nonstopDep,
    hasNonstopRet: !!nonstopRet,
    cheapestDepOverall: cheapestDep,
    finalSummary
  };
}

