const allCombos = JSON.parse((await read("tmp://all_combinations.json")).text);

const summary = allCombos.map((c, i) => {
  // Parse depLabel
  // e.g. "From 501 US dollars round trip total. Nonstop flight with American. Leaves Jacksonville International Airport at 7:40 AM on Wednesday, October 14 and arrives at Phoenix Sky Harbor International Airport at 9:18 AM on Wednesday, October 14. Total duration 4 hr 38 min. 1 carry-on bag included. 0 checked bags included. Select flight"
  const depTimeMatch = c.depLabel?.match(/Leaves [^a]+at ([\d:]+\s*[AP]M).*?arrives [^a]+at ([\d:]+\s*[AP]M)/);
  const retTimeMatch = c.retLabel?.match(/Leaves [^a]+at ([\d:]+\s*[AP]M).*?arrives [^a]+at ([\d:]+\s*[AP]M)/);

  // Parse booking options
  // Find price, tiers
  const tiers = [];
  const bo = c.finalSummary?.bookingOptions || [];
  for (let j = 0; j < bo.length; j++) {
    if (['Basic Economy', 'Main Cabin', 'Main Plus', 'Main Select', 'First'].includes(bo[j])) {
      tiers.push({
        tier: bo[j],
        price: bo[j+1],
        details: bo.slice(j+2, j+10).filter(x => !['Basic Economy', 'Main Cabin', 'Main Plus', 'Main Select', 'First', 'Continue'].includes(x))
      });
    }
  }

  return {
    index: i + 1,
    outDate: c.outDate,
    retDate: c.retDate,
    nights: c.nights,
    hasNonstopOut: c.hasNonstopOut,
    hasNonstopRet: c.hasNonstopRet,
    depTimes: depTimeMatch ? `${depTimeMatch[1]} -> ${depTimeMatch[2]}` : "not found",
    retTimes: retTimeMatch ? `${retTimeMatch[1]} -> ${retTimeMatch[2]}` : "not found",
    selectedFlights: c.finalSummary?.selectedFlights,
    tiers: tiers.slice(0, 2),
    cheapest1StopDep: c.cheapestDepOverall?.isNonstop ? "N/A (cheapest is nonstop)" : `${c.cheapestDepOverall?.airline} ($${c.cheapestDepOverall?.price})`
  };
});

console.log(JSON.stringify(summary, null, 2));

