const allCombos = JSON.parse((await read("tmp://all_combinations.json")).text);

const results = allCombos.map((c, i) => {
  const sf = c.finalSummary?.selectedFlights || [];

  // sf looks like:
  // ["Selected flights","Track prices","Wed, Oct 14","7:40 AM","–","9:18 AM","American","4 hr 38 min","JAX–PHX","Nonstop", ..., "Fri, Oct 16","3:59 PM","–","10:51 PM","American","3 hr 52 min","PHX–JAX","Nonstop", ...]

  // Find date lines or flight lines
  // Outbound:
  const outDateStr = sf[2]; // e.g. "Wed, Oct 14"
  const outDepTime = sf[3]; // "7:40 AM"
  const outArrTime = sf[5]; // "9:18 AM"
  const outAirline = sf[6]; // "American"
  const outDuration = sf[7]; // "4 hr 38 min"
  const outRoute = sf[8]; // "JAX–PHX"
  const outStops = sf[9]; // "Nonstop"

  // Find return flight starting index (looks for day like "Fri,", "Sat,", "Sun,")
  let retIdx = -1;
  for (let j = 10; j < sf.length; j++) {
    if (/^(Mon|Tue|Wed|Thu|Fri|Sat|Sun),/.test(sf[j])) {
      retIdx = j;
      break;
    }
